output_text:
[
  {
    "id": "must_collect_entry_cart",
    "text": "A shopper must take the waiting cart from the entrance cart depot before completing the trip.",
    "abstraction": {
      "state_properties": {
        "cart_depot_cell": "at(1,5)",
        "entry_cart_waiting": "cartAt(1,5)",
        "at_entry_cart_depot": {
          "and": [
            "cart_depot_cell",
            "entry_cart_waiting"
          ]
        }
      },
      "events": {
        "collect_entry_cart": {
          "pre": {
            "and": [
              "at_entry_cart_depot",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "collect_entry_cart"
    }
  },
  {
    "id": "no_item_pickup_without_cart",
    "text": "Merchandise may only be picked up when the shopper has a cart and is not already carrying something by hand.",
    "abstraction": {
      "state_properties": {
        "carrying_cart": "hasCart",
        "hands_occupied": "handFull"
      },
      "events": {
        "item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "item_pickup",
          {
            "or": [
              {
                "not": "carrying_cart"
              },
              "hands_occupied"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "front_interaction_is_cart_return",
    "text": "The front cell is a cart-return bay, so any interaction there must be leaving the cart rather than another kind of interaction.",
    "abstraction": {
      "state_properties": {
        "front_return_cell": "at(0,1)"
      },
      "events": {
        "front_interaction": {
          "pre": {
            "and": [
              "front_return_cell",
              "INTERACT"
            ]
          },
          "post": null
        },
        "front_cart_return": {
          "pre": {
            "and": [
              "front_return_cell",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "front_interaction",
          {
            "not": "LEAVE_CART"
          }
        ]
      }
    }
  },
  {
    "id": "after_items_return_cart",
    "text": "After taking any required item, the shopper must eventually return the cart to the front return bay before leaving.",
    "abstraction": {
      "state_properties": {
        "front_return_cell": "at(0,1)",
        "cart_parked_front": "cartAt(0,1)"
      },
      "events": {
        "item_taken": {
          "pre": "PICKUP_ITEM",
          "post": null
        },
        "cart_returned_front": {
          "pre": {
            "and": [
              "front_return_cell",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_front"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_taken",
      "discharge": "cart_returned_front"
    }
  },
  {
    "id": "return_cart_only_at_front",
    "text": "A cart may only be put down at the designated front return bay.",
    "abstraction": {
      "state_properties": {
        "front_return_cell": "at(0,1)"
      },
      "events": {
        "leave_cart_action": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leave_cart_action",
          {
            "not": "front_return_cell"
          }
        ]
      }
    }
  },
  {
    "id": "no_exit_before_cart_parked_front",
    "text": "The shopper may not exit until the cart is parked at the front return bay.",
    "abstraction": {
      "state_properties": {
        "cart_parked_front": "cartAt(0,1)"
      },
      "events": {
        "store_exit": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "store_exit",
          {
            "not": "cart_parked_front"
          }
        ]
      }
    }
  },
  {
    "id": "exit_empty_handed_without_cart",
    "text": "A shopper must leave the store as a pedestrian, without pushing a cart or carrying goods by hand.",
    "abstraction": {
      "state_properties": {
        "encumbered": {
          "or": [
            "hasCart",
            "handFull"
          ]
        }
      },
      "events": {
        "store_exit": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "store_exit",
          "encumbered"
        ]
      }
    }
  },
  {
    "id": "no_unattended_cart_in_aisles",
    "text": "A shopper must not abandon a cart anywhere except the entrance depot or the front return bay.",
    "abstraction": {
      "state_properties": {
        "cart_at_entrance_depot": "cartAt(1,5)",
        "cart_at_front_return": "cartAt(0,1)",
        "cart_at_official_station": {
          "or": [
            "cart_at_entrance_depot",
            "cart_at_front_return"
          ]
        },
        "not_with_cart": {
          "not": "hasCart"
        },
        "unattended_cart_off_station": {
          "and": [
            "not_with_cart",
            {
              "not": "cart_at_official_station"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "unattended_cart_off_station"
    }
  }
]
